from pathlib import Path
import json,html,markdown
OUT=Path(__file__).resolve().parent
items=json.loads((OUT/'packages.json').read_text(encoding='utf-8'))
css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:#f4f0e8;color:#272820;font:18px/1.7 Georgia,serif}main{max-width:1120px;margin:auto;padding:52px 28px}h1{font-size:clamp(34px,5vw,62px);line-height:1.1;font-weight:400;margin:18px 0}h2{font-size:32px;font-weight:400;margin:45px 0 18px}h3{font-size:24px}a{color:#854250;text-underline-offset:4px}nav,.eyebrow,.label,button,summary,.small{font-family:system-ui,sans-serif}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#676456}.lead{font-size:23px;max-width:790px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#fffcf5;border:1px solid #d8d3c5;padding:24px;border-radius:5px}.card:first-child{border-top:4px solid #854250}.label{font-size:12px;color:#68614f;letter-spacing:.04em}.card h3{margin:8px 0}.card p{margin:15px 0}.small{font-size:14px;color:#625e52}.path{font:12px/1.55 Consolas,monospace;overflow-wrap:anywhere;background:#e8e3d8;padding:10px;user-select:all}.prompt{font:15px/1.6 system-ui,sans-serif;border-left:3px solid #854250;padding:18px;background:#fffaf0}nav{display:flex;gap:20px;flex-wrap:wrap;margin:30px 0;font-size:15px}section{border-top:1px solid #d8d3c5;padding-top:10px;margin-top:32px}details{border:1px solid #d8d3c5;padding:18px 24px;margin-top:24px}summary{cursor:pointer;font-weight:600}details[open]>summary{margin-bottom:24px}table{font:14px/1.55 system-ui,sans-serif;border-collapse:collapse;display:block;overflow-x:auto}td,th{padding:12px;text-align:left;border-bottom:1px solid #d8d3c5;min-width:165px;vertical-align:top}code{font:.85em Consolas,monospace;overflow-wrap:anywhere}blockquote{border-left:3px solid #aaa08d;margin-left:0;padding-left:20px}.reading{max-width:820px;margin:auto}.reading p{margin-bottom:22px}footer{font:13px/1.6 system-ui,sans-serif;border-top:1px solid #d8d3c5;padding:28px 0;margin-top:45px}@media(max-width:700px){.cards{grid-template-columns:1fr}main{padding:28px 18px}.lead{font-size:20px}}'''
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Claude — the next encounter and writing pass</title><style>'+css+'</style></head><body><main>'
page+='''<div class="eyebrow">Ada Research · Working handoff · 23 September 2026</div><h1>Give the next sentence<br>something to encounter.</h1><p class="lead">The strongest next work differs by sequence. Some prose needs space to breathe. Some rooms need a consequence worth writing about.</p><p><strong>Start Claude with Soft Bodies, one hall: Cloth Physics.</strong> It already has material to think with. Machine Learning needs the largest computational additions among these candidates. Boolean Works is the clearest individual example of fault-report prose. QFEP needs selective work on its panel-led passages.</p><nav><a href="#assignments">Five ready packets</a><a href="#send">What to send</a><a href="#assessment">Assessment</a><a href="#brief">Writing direction</a></nav><section id="assignments"><h2>One initial hall per assignment</h2><p>Each packet includes the whole sequence for context. These are five available assignments, not a request to rewrite five sequences at once. No message has been sent to Claude.</p><div class="cards">'''
for n,r in enumerate(items):
 seq=r['sequence'];folder='packages/'+seq+'/'
 zip_path=str((OUT/r['zip']).resolve())
 page+=f'''<article class="card"><div class="label">{n+1:02d} · {r['halls']} halls in context</div><h3>{html.escape(r['title'])}</h3><p><strong>{html.escape(seq)}</strong><br>First: <code>{html.escape(r['pilot'])}</code></p><p><a href="{folder}ASSIGNMENT.md">Specific assignment</a> · <a href="{folder}review.md">Full reading packet</a> · <a href="{folder}COPY_TO_CLAUDE.md">Prompt to copy</a></p><p class="small">Source ZIP · {r['bytes']/1048576:.1f} MB · includes companion drafts, source plans, reference chapters and placed artifact sources.</p><div class="path">{html.escape(zip_path)}</div></article>'''
page+='''</div></section><section id="send"><h2>What to give Claude</h2><p><strong>Online:</strong> attach the chosen ZIP from the local path above and its <em>review.md</em>, then paste the prompt below. The ZIP has the implementation and spatial context; the reading file has the full manuscript and writing instruction. The review server serves text and images but does not currently deliver ZIP downloads, so select the local ZIP in Claude’s attachment picker.</p><p><strong>Local Claude:</strong> give it the chosen packet folder and the same prompt. Source snapshots preserve the starting point; recheck current files before editing shared working files.</p>'''
page+='<div class="prompt">'+html.escape((OUT/'packages/softbodies/COPY_TO_CLAUDE.md').read_text(encoding='utf-8'))+'</div>'
page+='''<p>The first return should contain a developed passage or hall beside the original, the encounter that carries it, and evidence or a clearly labelled build task. Judge that pilot before extending its voice across the sequence.</p></section>'''
page+='<section id="assessment"><h2>The reasons for these choices</h2><p><a href="ASSESSMENT.md">Full assessment as Markdown</a></p>'+markdown.markdown((OUT/'ASSESSMENT.md').read_text(encoding='utf-8'),extensions=['extra'])+'</section>'
page+='<section id="brief"><h2>The new writing direction</h2><p><a href="WRITING_BRIEF.md">Give Claude this brief</a></p><details><summary>Read the complete brief here</summary><div class="reading">'+markdown.markdown((OUT/'WRITING_BRIEF.md').read_text(encoding='utf-8'),extensions=['extra'])+'</div></details></section>'
page+='''<footer>Prepared from current local working files, including unpublished changes. Earlier reports remain dated evidence. This handoff changes no canonical chapter or artifact and runs no new museum test. Sources and archive hashes are in the packet manifests. <a href="verification.json">Packaging checks</a>.</footer></main></body></html>'''
(OUT/'index.html').write_text(page,encoding='utf-8')
print('Built handoff reading page with current assignments and local ZIP paths.')
